import { Block } from './types'
import { blockIsInteractive } from './block-is-interactive'

/**
 * @returns the blocks that should be visible in the chat UI grouped by
 *     whether they are visible or collapsed. If `isGenerating`, we show all
 *     consecutive text, code, or animated-text blocks to end the message and
 *     any interactive blocks. If not `isGenerating`, we show all consecutive
 *     text, code, or animated text blocks to end the message without
 *     interactive blocks.
 */
export const getVisibleBlocks = ({
	blocks,
	isGenerating
}: {
	blocks: Block[]
	isGenerating: boolean
}) => {
	const lastBlock = blocks[blocks.length - 1]
	if (!lastBlock) {
		return { visible: [], collapsed: [] }
	}
	const visible: Block[] = []
	let done = false
	;[...blocks].reverse().forEach((block) => {
		if (done) return
		if (isGenerating) {
			const wouldFinish =
				block.type !== 'text' &&
				block.type !== 'animated-text' &&
				block.type !== 'code' &&
				!blockIsInteractive(block)
			if (wouldFinish) {
				if (visible.length === 0) {
					visible.push(block)
				}
			} else {
				visible.push(block)
			}
			done = wouldFinish
			return
		}
		if (
			block.type === 'code' ||
			block.type === 'text' ||
			block.type === 'animated-text' ||
			blockIsInteractive(block)
		) {
			visible.push(block)
		} else {
			done = true
		}
	})
	if (visible.length === 0) {
		visible.push(lastBlock)
	}

	const collapsed = blocks.filter((block) => !visible.includes(block))

	return {
		visible: visible.reverse().sort((a, b) => {
			// interactive blocks MUST go last
			if (blockIsInteractive(a) && !blockIsInteractive(b)) return 1
			if (!blockIsInteractive(a) && blockIsInteractive(b)) return -1
			return blocks.indexOf(a) - blocks.indexOf(b)
		}),
		collapsed
	}
}
